from author import *
b=[]
def add(a,n,ops,focus='viewport'):b.append(act(a,n,ops,focus))
def prop(k,v,node='Burst',**kw):return setp(k,v,node,**kw)
def process(k,v,node='Burst'):
 query={'particle_flag_disable_z':'disable z','initial_velocity_min':'initial velocity','initial_velocity_max':'initial velocity','scale_min':'scale','scale_max':'scale','scale_curve':'scale','color_ramp':'color'}.get(k,k.replace('_',' '))
 return prop(k,v,node,resource_property='process_material',restart=True,filter=query)
def key(k,pressed=True,**kw):return dict(op='game_input',key=k,pressed=pressed,**kw)
def gameprop(k,v):return dict(op='game_input',property=k,value=v)
A='Make The First Particle Visible'
add(A,'This is our test arena: one marker, a dark half, and a light half. Keep those references steady. A useful particle effect has to read at the size and contrast where the game will use it.',[dict(op='open',path='res://arena.tscn'),at(1,op='zoom')])
add(A,'Add G P U Particles Two D to the arena. The node controls how many particles exist and when they are born. Its empty process slot is the next part of the construction, not evidence that the effect is finished.',[dict(op='add',class_name='GPUParticles2D',name='Burst',properties={'position':{'v2':[0,100]},'amount':48,'lifetime':.8,'use_fixed_seed':True,'seed':7270},checkpoint=True)])
add(A,'Create a Particle Process Material in that slot. This resource owns motion and variation. Turn Disable Z on, so this two-dimensional effect stays in its plane. The node and its resource answer different questions.',[prop('process_material',{'new':'ParticleProcessMaterial'}),at(.5,**process('particle_flag_disable_z',True)),at(4,op='resource',node='Burst',property='process_material')])
add(A,'The first particles are tiny. Assign our procedural soft-dot texture and they become legible. This is the draw part of the effect. A running simulation can be difficult to see when its visible mark is missing.',[prop('texture',{'resource':'res://assets/soft-dot.tres'}),at(.4,**process('scale_min',.4)),at(.7,**process('scale_max',.8))])
add(A,'Set the launch direction upward, with negative Y. Give it a speed range from one hundred to two hundred twenty. New particles rise away from the marker. Speed changes travel; it does not change how many are born.',[process('direction',{'v3':[0,-1,0]}),at(.3,**process('initial_velocity_min',100)),at(.6,**process('initial_velocity_max',220))])
add(A,'Gravity is positive one hundred forty on Y. The launch begins upward, then bends down. Set gravity to zero for a straight comparison. Restore it before changing the burst schedule, so we can still explain the difference.',[process('gravity',{'v3':[0,140,0]}),at(4,**process('gravity',{'v3':[0,0,0]})),at(8,**process('gravity',{'v3':[0,140,0]}))])
add(A,'Now inspect the resource and the node separately. Direction, gravity, and speed live in the process material. Amount, lifetime, and one shot live on the particle node. Looking in the right place makes tuning much less mysterious.',[dict(op='resource',node='Burst',property='process_material'),at(5,op='select',node='Burst')])
add(A,'Keep the texture fixed and move the same effect across both backgrounds. Its pale center reads differently against the light area. We are checking visibility, not changing the physics to compensate for a drawing problem.',[prop('position',{'v2':[-250,100]}),at(5,**prop('position',{'v2':[250,100]})),at(9,**prop('position',{'v2':[0,100]}))])
A='Shape A Burst'
add(A,'Turn One Shot on. Restart the emitter and watch one complete emission cycle. It stops making new particles, while the existing particles finish their lives. One shot alone does not make every particle appear at the same instant.',[setp('heading',A),at(.3,**prop('one_shot',True)),at(.6,op='call',node='Burst',method='restart'),at(4,op='call',node='Burst',method='restart')])
add(A,'Set Explosiveness to one and restart. The particles now arrive together, giving the event a crisp onset. Compare it with zero, where births are distributed through the cycle. This control changes timing, not the texture.',[prop('explosiveness',1),at(.3,op='call',node='Burst',method='restart'),at(4,**prop('explosiveness',0)),at(4.3,op='call',node='Burst',method='restart'),at(8,**prop('explosiveness',1)),at(8.3,op='call',node='Burst',method='restart')])
add(A,'Open spread to one hundred eighty degrees. The burst expands around its origin. Narrow it to twenty-five and it points like a small spray. Pick the silhouette that communicates the event, then keep that choice consistent.',[process('spread',180),at(4,**process('spread',25)),at(8,**process('spread',180))])
add(A,'Forty-eight particles make this burst. Double the amount and replay it, then return to forty-eight. The denser result is not automatically clearer. Count is a design control, and it is only one part of rendering cost.',[prop('amount',96,restart=True),at(4,**prop('amount',48,restart=True)),at(8,op='call',node='Burst',method='restart')])
add(A,'Attach the size curve. Each particle starts small, grows quickly, and shrinks toward its exit. The curve follows normalized lifetime, so the same shape applies to every particle even when the overall lifetime changes.',[process('scale_curve',{'resource':'res://assets/size-over-life.tres'}),at(4,op='call',node='Burst',method='restart'),at(8,op='call',node='Burst',method='restart')])
add(A,'Attach the color ramp. A pale hot center gives way to orange and then zero alpha. The gradual fade belongs to the drawing, while lifetime still controls when the particle dies. Those two endings should agree.',[process('color_ramp',{'resource':'res://assets/color-over-life.tres'}),at(4,op='call',node='Burst',method='restart'),at(8,op='call',node='Burst',method='restart')])
add(A,'Lengthen lifetime from eight tenths to one point four seconds and replay. The particles have more time to travel. Restore eight tenths for this pickup: a short event needs a short, readable acknowledgement, rather than a lingering cloud.',[prop('lifetime',1.4,restart=True),at(5,**prop('lifetime',.8,restart=True)),at(9,op='call',node='Burst',method='restart')])
add(A,'Save the burst as its own scene, initially inactive. Give its visibility rectangle room for the full path. The saved resource now carries the emission, motion, and drawing choices together, ready for a trigger to instantiate it.',[prop('visibility_rect',{'rect':[-400,-400,800,800]}),at(.3,**prop('local_coords',False)),at(.6,**prop('emitting',False)),at(1,op='save_branch',node='Burst',path='res://effects/pickup_burst.tscn'),at(3,op='save',checkpoint=True)])
A='Make It Respond'
add(A,'This is the trigger code. Space instantiates the saved scene at the marker’s position. The finished signal removes that temporary instance. We keep a count because a good-looking burst can still leave an invisible owner behind.',[dict(op='script',path='res://arena.gd',line=38)],'code')
add(A,'Run the arena and press Space through its ordinary input path. These inputs are scripted for the recording. Watch the burst complete, then the instance counter return to zero. The result comes from the same scene we just saved.',[dict(op='play_custom',path='res://game.tscn'),at(3,**key('Space')),at(3.2,**key('Space',False)),at(7,**key('Space')),at(7.2,**key('Space',False))],'game')
add(A,'Move the marker left and trigger again. Then move right and repeat. Each instance gets the event’s current position. The scene is reusable because it contains the effect, while the caller supplies where and when it belongs.',[key('Left'),at(1,**key('Left',False)),at(1.3,**key('Space')),at(1.5,**key('Space',False)),at(4,**key('Right')),at(6,**key('Right',False)),at(6.3,**key('Space')),at(6.5,**key('Space',False))],'game')
add(A,'Here is a staged ownership fault. Put the burst beneath the marker, then hide the marker on activation. The event still creates an instance, but its parent hides the picture. Emitting and visible are different facts.',[gameprop('staged_hidden_owner',True),at(.4,**key('Space')),at(.6,**key('Space',False))],'game')
add(A,'Repair the owner: place the effect under the visible arena. Leave the marker hidden and trigger again. The burst now survives the marker’s visibility change. Choose an owner whose lifetime matches the visual job, rather than the object that happened to trigger it.',[gameprop('staged_hidden_owner',False),at(.4,**key('Space')),at(.6,**key('Space',False)),at(5,**key('Space')),at(5.2,**key('Space',False))],'game')
add(A,'Reset, then trigger repeatedly. Each finished instance cleans itself up, so the counter comes back to zero. This checks ownership and cleanup. It does not prove that every future game event will call the effect at the right moment.',[key('R'),at(.2,**key('R',False)),at(1,**key('Space')),at(1.2,**key('Space',False)),at(3,**key('Space')),at(3.2,**key('Space',False)),at(5,**key('Space')),at(5.2,**key('Space',False))],'game')
A='Turn A Burst Into A Stream'
add(A,'Stop play and duplicate the particle node as Trail. Make its process material unique before editing. The texture can remain shared. Sharing an image is useful; accidentally sharing the motion settings would retune the pickup as well.',[dict(op='stop'),at(1,op='duplicate',node='Burst',name='Trail'),at(2,op='unique',node='Trail',property='process_material'),at(3,**prop('visible',False))])
add(A,'Turn One Shot off and Explosiveness down to zero. The trail now produces a steady stream. Give it a two-second lifetime and forty-eight particles. At steady state, amount divided by lifetime describes its nominal birth rate.',[prop('one_shot',False,'Trail'),at(.3,**prop('explosiveness',0,'Trail')),at(.6,**prop('lifetime',2,'Trail')),at(.9,**prop('amount',48,'Trail')),at(1.2,**prop('emitting',True,'Trail'))])
add(A,'Aim the trail upward, narrow the spread, and remove gravity. A slow speed range makes rising embers. We have changed the visual job from a momentary acknowledgement to an ongoing condition, using the same basic particle machinery.',[process('direction',{'v3':[0,-1,0]},'Trail'),at(.3,**process('spread',15,'Trail')),at(.6,**process('gravity',{'v3':[0,0,0]},'Trail')),at(.9,**process('initial_velocity_min',45,'Trail')),at(1.2,**process('initial_velocity_max',85,'Trail'))])
add(A,'Move the source with local coordinates off. Newly born particles follow the marker, while older ones remain in world space. Turn local coordinates on and the existing cloud moves with its source. That difference decides whether you get a trail or an attached aura.',[setp('move_source',True),at(.4,**prop('local_coords',False,'Trail')),at(5,**prop('local_coords',True,'Trail')),at(9,**prop('local_coords',False,'Trail'))])
add(A,'Turn the stream condition off. New births stop, and the existing embers finish. Turn it on to resume. A continuous effect needs a condition that can become false; restarting it every frame is not a substitute for that condition.',[setp('stream_enabled',False),at(5,**setp('stream_enabled',True))])
add(A,'Inspect the visibility rectangle around the moving trail. A tiny bound may cull a still-visible effect when its emitter leaves the view. Keep a conservative box for the measured motion, and test it with the actual camera rather than guessing from the origin.',[prop('visibility_rect',{'rect':[-20,-20,40,40]},'Trail'),at(5,**prop('visibility_rect',{'rect':[-450,-400,900,800]},'Trail')),at(8,**setp('move_source',False))])
add(A,'Convert a duplicate to C P U Particles Two D. The settings now live directly on the node. Compare the visible result, then choose for your target and required features. Conversion is a starting point; GPU-specific features still need an explicit check.',[dict(op='cpu_convert',node='Trail',name='CpuComparison'),at(5,op='select',node='CpuComparison')])
add(A,'Save the continuous scene and the test arena. The pickup has a real input trigger and finished cleanup; the trail has a condition and a deliberate coordinate space. Those contracts make the effects useful outside this demonstration.',[prop('visible',False,'CpuComparison'),at(.3,**prop('visible',True,'Trail')),at(.6,op='save_branch',node='Trail',path='res://effects/rising_trail.tscn'),at(1,op='save',checkpoint=True)])
d=dict(slug='claude-liam-lecture-building-2d-particle-effects-in-godot',title='Building 2D Particle Effects in Godot',payoff='Build a burst and a trail you can reuse',summary='Build, trigger, and test a burst and a continuous effect.',framing='How do we make particles behave on purpose? We will connect emission, motion, and drawing, then test the effect through the input that uses it.',question='How do we make particles\nbehave by chance?',trigger='chance',replacement='design',terms=[dict(term='Emitter',meaning='The source of new particles'),dict(term='Material',meaning='A resource that controls behavior or drawing'),dict(term='Signal',meaning='A notification that something happened'),dict(term='Lifetime',meaning='How long one particle remains alive')],body=b,recap=['A visible effect needs emission, motion, and drawing.','Burst timing and lifetime have different jobs.','Curves shape appearance over each particle’s age.','A visible owner and finished cleanup make triggers reliable.','A stream follows a condition and a coordinate space.','Reusable scenes still need tests on their target.'],prompt='Give the marker a pickup burst and a moving trail. Predict what happens when the marker hides or stops. Test both positions and preserve one before-and-after revision.',checks=['Check: repeated bursts remain visible and clean up.','Check: trail emission follows the stated condition.'],coverage='Four acts cover visible GPU setup, Disable Z, texture, node/resource separation, 2D gravity, contrast, one-shot/explosiveness, count, spread/speed, scale curve, color/alpha, lifetime, reusable scenes, ordinary scripted input, two positions, hidden-owner fault and repair, finished cleanup, continuous conditions, local/world coordinates, bounds and CPU conversion. A diagnostic input file injects InputEventKey through Godot; it does not call spawn_burst directly.',facts='All parameters are teaching settings, not benchmark results. GPU Amount is a count. Positive Y points down in the 2D scene. One Shot and Explosiveness are distinct. finished cleanup is applicable to the one-shot GPU scene. CPU conversion is inspected, not assumed feature-equivalent. Tiny bounds are demonstrated and corrected; any particular culling result must be observed rather than promised.')
Path('film2.json').write_text(json.dumps(d,indent=2));author(d)
